// ================= CONFIGURE AQUI =================
// Chave do AeroDataBox (plano grátis serve para teste; uso comercial exige plano pago).
const AERODATABOX_KEY = "COLE_AQUI_A_CHAVE_DO_AERODATABOX";
// Onde a chave foi criada: "apimarket" (api.market) ou "rapidapi" (rapidapi.com).
const MARKETPLACE = "apimarket";
// WhatsApp que envia (número da agência no WTS/Frédy, só números com 55) e quem recebe os alertas (admins).
const CANAL = "55DDDNUMERO";
const ADMINS = ["55DDDNUMERO"];
// A partir de quantos minutos de atraso avisar.
const ATRASO_MINIMO_MIN = 30;
// Mandar mensagem também quando não houver nenhum alerta ("tudo certo hoje").
const AVISAR_SEM_ALERTA = false;
// Pausa entre consultas (o plano grátis limita a velocidade).
const ESPERA_MS = 1500;
// ==================================================

const base = MARKETPLACE === "rapidapi" ? "https://aerodatabox.p.rapidapi.com" : "https://prod.api.market/api/v1/aedbx/aerodatabox";
const headers = MARKETPLACE === "rapidapi" ? { "X-RapidAPI-Key": AERODATABOX_KEY, "X-RapidAPI-Host": "aerodatabox.p.rapidapi.com" } : { "x-api-market-key": AERODATABOX_KEY };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
// horário local "AAAA-MM-DD HH:mm" (AeroDataBox) ou "AAAA-MM-DDTHH:mm" (gestão) -> minutos, comparando a hora do relógio local
const minutes = (s) => (s ? Date.parse(String(s).slice(0, 16).replace(" ", "T") + ":00Z") / 60000 : null);
const hhmm = (s) => (s ? String(s).slice(11, 16) : "?");
const ddmm = (s) => (s ? `${String(s).slice(8, 10)}/${String(s).slice(5, 7)}` : "");

const body = $input.first().json;
const voos = Array.isArray(body.data) ? body.data : [];
const alertas = [];
const semDados = [];
let conferidos = 0;

for (const v of voos) {
  const url = `${base}/flights/number/${encodeURIComponent(v.voo)}/${v.partida.slice(0, 10)}?dateLocalRole=Departure&withAircraftImage=false&withLocation=false`;
  let lista = [];
  try {
    const r = await this.helpers.httpRequest({ method: "GET", url, headers, json: true, timeout: 20000 });
    lista = Array.isArray(r) ? r : [];
  } catch (e) {
    semDados.push(`${v.companhia} ${v.numero} ${v.origem}→${v.destino}: erro na consulta (${String(e.message || e).slice(0, 80)})`);
    await sleep(ESPERA_MS);
    continue;
  }
  conferidos++;
  const f = lista.find((x) => x?.departure?.airport?.iata === v.origem) || lista[0];
  const quem = `${v.cliente} (${v.venda}${v.passageiros > 1 ? ` · ${v.passageiros} pax` : ""})${v.whatsappCliente ? ` · ${v.whatsappCliente}` : ""}`;
  const voo = `${v.companhia} ${v.numero} ${v.origem}→${v.destino} ${ddmm(v.partida)} ${hhmm(v.partida)}`;
  if (!f) {
    semDados.push(`${voo}: o AeroDataBox não achou este voo`);
    await sleep(ESPERA_MS);
    continue;
  }
  const dep = f.departure || {};
  const programado = dep.scheduledTime?.local;
  const revisado = dep.revisedTime?.local || dep.predictedTime?.local;
  const linhas = [];
  if (f.status === "Canceled") linhas.push("❌ CANCELADO pela companhia");
  if (f.status === "CanceledUncertain") linhas.push("⚠️ Possível cancelamento (a confirmar com a companhia)");
  if (f.status === "Diverted") linhas.push(`↪️ Desviado${f.arrival?.airport?.iata ? ` para ${f.arrival.airport.iata}` : ""}`);
  if (programado && Math.abs(minutes(programado) - minutes(v.partida)) >= 15) linhas.push(`🕑 Horário mudou na companhia: agora ${hhmm(programado)} (na venda ${hhmm(v.partida)})`);
  if (programado && revisado && minutes(revisado) - minutes(programado) >= ATRASO_MINIMO_MIN) linhas.push(`⏰ Atrasado: deve sair ${hhmm(revisado)} (previsto ${hhmm(programado)})`);
  else if (f.status === "Delayed") linhas.push("⏰ Companhia informa atraso");
  if (linhas.length) {
    if (dep.terminal || dep.gate) linhas.push(`🚪 ${dep.terminal ? `Terminal ${dep.terminal}` : ""}${dep.terminal && dep.gate ? " · " : ""}${dep.gate ? `Portão ${dep.gate}` : ""}`);
    alertas.push(`*${voo}*\n${quem}\n${linhas.join("\n")}`);
  }
  await sleep(ESPERA_MS);
}

if (!alertas.length && !AVISAR_SEM_ALERTA) return [];
const hoje = ddmm(body.hoje || new Date().toISOString());
let texto = alertas.length ? `✈️ *Alertas de voos · ${hoje}*\n\n${alertas.join("\n\n")}` : `✈️ Voos conferidos · ${hoje}: nenhum alerta (${conferidos} voo(s)).`;
if (semDados.length) texto += `\n\n_Sem informação no AeroDataBox:_\n${semDados.slice(0, 15).join("\n")}`;
texto += `\n\n${conferidos} de ${voos.length} voo(s) conferido(s). Dados: AeroDataBox.`;
return ADMINS.filter(Boolean).map((to) => ({ json: { from: CANAL, to, text: texto.slice(0, 4000), alertas: alertas.length } }));
